const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/installation_requests',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    developer_app_id: 'SOME_STRING_VALUE',
    implicit: 'SOME_BOOLEAN_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/installation_requests?company_id=SOME_INTEGER_VALUE&developer_app_id=SOME_STRING_VALUE&implicit=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/installation_requests',
  headers: {'content-type': 'application/json'},
  body: {
    company_id: 224087,
    developer_app_id: '396e4944-5044-4b72-bb6b-6827d3ab2e75',
    notes: 'Requesting installation for use on project XYZ',
    implicit: true
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/installation_requests"),
    Content = new StringContent("{\"company_id\":224087,\"developer_app_id\":\"396e4944-5044-4b72-bb6b-6827d3ab2e75\",\"notes\":\"Requesting installation for use on project XYZ\",\"implicit\":true}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
